// Square photo slots only. Cover art, banners and chat attachments retain their own ratios.
const croppedPhotos=new WeakMap();
async function cropPhotoEditor(file){
 if(croppedPhotos.has(file))return croppedPhotos.get(file);
 if(!['image/jpeg','image/png','image/webp'].includes(file?.type)||file.size>5*1024*1024)throw new Error('JPG·PNG·WebP, 5MB 이하 사진을 선택해주세요.');
 const decode=async f=>{const b=await decodeUploadImage(f);if(!b.width||!b.height||b.width*b.height>64000000){b.close();throw Error('이미지가 너무 커요. 가로·세로 크기를 줄여주세요.');}return b;};
 let bitmap=await decode(file),zoom=1,x=.5,y=.5;
 const modal=document.createElement('dialog');modal.className='photo-crop-dialog';modal.innerHTML='<h2>사진 편집</h2><p>사진을 움직이거나 확대해 정사각형으로 맞춰주세요.</p><canvas width="800" height="800" aria-label="저장할 사진 미리보기"></canvas><label>확대·축소<input type="range" min="1" max="4" step=".01" value="1"></label><label class="small-button">다른 사진 선택<input type="file" accept="image/jpeg,image/png,image/webp" class="sr-only"></label><div class="inline-actions"><button class="small-button" data-crop-cancel>취소</button><button class="primary-button" data-crop-save>사진 사용</button></div><p role="alert"></p>';
 document.body.append(modal);modal.showModal();const canvas=modal.querySelector('canvas'),slider=modal.querySelector('[type=range]'),pointers=new Map();
 const rect=()=>{const size=Math.min(bitmap.width,bitmap.height)/zoom;return {size,x:(bitmap.width-size)*x,y:(bitmap.height-size)*y};};
 const draw=()=>{const r=rect();canvas.getContext('2d').drawImage(bitmap.source||bitmap,r.x,r.y,r.size,r.size,0,0,800,800);};
 const scale=v=>{zoom=Math.max(1,Math.min(4,v));slider.value=zoom;draw();};slider.oninput=()=>scale(Number(slider.value));
 canvas.onwheel=e=>{e.preventDefault();scale(zoom-e.deltaY*.002);};
 canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});};
 canvas.onpointermove=e=>{const prev=pointers.get(e.pointerId);if(!prev)return;const points=[...pointers.entries()],r=rect();if(points.length===2){const other=points.find(([id])=>id!==e.pointerId)[1],before=Math.hypot(prev.x-other.x,prev.y-other.y),after=Math.hypot(e.clientX-other.x,e.clientY-other.y);if(before)scale(zoom*after/before);}else{const ratio=r.size/canvas.getBoundingClientRect().width;x=bitmap.width===r.size?.5:Math.max(0,Math.min(1,x-(e.clientX-prev.x)*ratio/(bitmap.width-r.size)));y=bitmap.height===r.size?.5:Math.max(0,Math.min(1,y-(e.clientY-prev.y)*ratio/(bitmap.height-r.size)));draw();}pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});};
 canvas.onpointerup=canvas.onpointercancel=e=>pointers.delete(e.pointerId);
 modal.querySelector('[type=file]').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024)throw Error('JPG·PNG·WebP, 5MB 이하 사진을 선택해주세요.');const next=await decode(f);bitmap.close();bitmap=next;zoom=1;x=y=.5;slider.value=1;draw();}catch(err){modal.querySelector('[role=alert]').textContent=err.message;}};
 draw();return new Promise((resolve,reject)=>{let finished=false;const done=(value)=>{if(finished)return;finished=true;bitmap.close();modal.close();modal.remove();if(value){croppedPhotos.set(file,value);croppedPhotos.set(value,value);resolve(value);}else reject(new Error('사진 편집을 취소했어요. 기존 사진은 유지됩니다.'));};modal.querySelector('[data-crop-cancel]').onclick=()=>done(null);modal.oncancel=e=>{e.preventDefault();done(null);};modal.onclick=e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)done(null);}};modal.querySelector('[data-crop-save]').onclick=()=>canvas.toBlob(blob=>{if(blob)done(new File([blob],'photo.webp',{type:blob.type}));},'image/webp',.9);});
}
function photoLightbox(src,label){
 const d=document.createElement('dialog');d.className='photo-lightbox';d.innerHTML='<button class="small-button" aria-label="사진 확대 닫기">닫기</button><img src="'+esc(src)+'" alt="'+esc(label)+'">';document.body.append(d);d.showModal();const originalURL=location.href,marker='photo-'+Date.now();history.pushState({...history.state,photoLightbox:marker},'',location.href);let closed=false;const remove=()=>{if(closed)return;closed=true;d.close();d.remove();window.removeEventListener('popstate',onBack,true);};const onBack=e=>{if(location.href===originalURL){e.photoOverlayHandled=true;e.stopImmediatePropagation();}remove();};const close=()=>{if(history.state?.photoLightbox===marker)history.back();else remove();};d.querySelector('button').onclick=close;d.oncancel=e=>{e.preventDefault();close();};d.onclick=e=>{if(e.target===d)close();};window.addEventListener('popstate',onBack,{once:true,capture:true});
}
document.addEventListener('click',e=>{const b=e.target.closest('.profile-preview-photo');if(b){const img=b.querySelector('img');if(img){e.preventDefault();e.stopPropagation();photoLightbox(img.currentSrc||img.src,img.alt);}}});

const photoCropPending=new WeakMap();
async function cropPhoto(file){if(!photoCropPending.has(file))photoCropPending.set(file,cropPhotoEditor(file));try{return await photoCropPending.get(file);}catch(e){photoCropPending.delete(file);throw e;}}
document.addEventListener('change',async e=>{const input=e.target;if(!input.matches('#public-profile-form input[type=file],#profile-gallery-upload input[type=file],#gallery-upload-form input[type=file],input[type=file][name=artist_image],input[type=file][name=producer_image]'))return;const selected=[...input.files],transfer=new DataTransfer();for(const file of selected){try{const photo=await cropPhoto(file);transfer.items.add(photo);}catch(err){toast(err.message);}}if(input.isConnected)input.files=transfer.files;});
